def next_greatest_letter(letters, target):
    lo, hi = 0, len(letters)

    while lo < hi:
        mid = (lo + hi) // 2
        if letters[mid] <= target:
            lo = mid + 1
        else:
            hi = mid

    return letters[lo % len(letters)]

